const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createHash}=require('node:crypto');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'/Users/toozservis/Developer/evidence-web-qa-runtime/node_modules/playwright');
const origin='http://127.0.0.1:18917',root=path.resolve(__dirname,'../..'),output=process.env.INCIDENT_QA_OUTPUT||'/Users/toozservis/Developer/evidence-admin-incidents-20261105/web-evidence';
const files=['web_admin/index.html','web_admin/admin.js','web_admin/activity.js','web_admin/incidents.js','web_admin/incidents.css','web/customer-features.js','web/customer-session.js','src/server/admin_session.js'];
const sha=data=>createHash('sha256').update(data).digest('hex'),pins=Object.fromEntries(files.map(file=>[file,sha(fs.readFileSync(path.join(root,file)))]));
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true}),setup=(await(await fetch(origin+'/qa/setup')).json()).web,proof=[],pending=[];try{for(const role of ['admin','user']){const context=await browser.newContext();await context.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());await context.addInitScript(({role,jwt})=>{sessionStorage.setItem(role==='admin'?'adminAccessToken':'customerWebAccessToken',jwt);sessionStorage.setItem(role==='admin'?'adminRole':'customerWebRole',role)}, {role,jwt:setup.users[role].jwt});const page=await context.newPage();page.on('response',r=>{let file=new URL(r.url()).pathname.slice(1);if(file==='admin-session.js')file='src/server/admin_session.js';if(pins[file]&&r.ok())pending.push(r.body().then(bytes=>{const digest=sha(bytes);assert.equal(digest,pins[file]);proof.push({role,file,sha256:digest});}));});await page.goto(origin+(role==='admin'?'/web_admin/index.html#incidents':'/web/customer.html'));await (role==='admin'?page.locator('#incident-list-status'):page.locator('[data-tab-key="customerOverview"]')).waitFor();await Promise.all(pending);await context.close();}for(const file of files){assert(proof.some(x=>x.file===file),'Browser did not load '+file);assert.equal(sha(fs.readFileSync(path.join(root,file))),pins[file]);}fs.writeFileSync(path.join(output,'source-pins.json'),JSON.stringify({status:'PASS',date:new Date().toISOString(),root,sourcePins:pins,loadedBrowserAssets:proof},null,2));console.log('PASS browser-loaded source hashes: '+files.length);}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
